use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityUserVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityUserAccessor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRelyingPartyVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityRelyingPartyAccessor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityTrustedClientAccessor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityRolesAccessor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityVersionVO;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\Accessor\PlatformIdentityVersionAccessor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Event\PlatformIdentityCreateEvent;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Event\PlatformIdentityUpdateEvent;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Event\PlatformIdentityDeleteEvent;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;

class PlatformIdentity extends PlatformIdentityRef
{
    use PlatformIdentityUserAccessor;
    use PlatformIdentityRelyingPartyAccessor;
    use PlatformIdentityTrustedClientAccessor;
    use PlatformIdentityRolesAccessor;
    use PlatformIdentityVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        PlatformIdentityUidVO|string $uid,
        PlatformIdentityUserVO|UserRef $user,
        PlatformIdentityRolesVO|PlatformIdentityRolesListRef| array |null $roles,
        PlatformIdentityRelyingPartyVO|RelyingPartyRef|null $relyingParty = null,
        PlatformIdentityTrustedClientVO|TrustedClientRef|null $trustedClient = null,
        PlatformIdentityVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_user = PlatformIdentityUserVO::from($user);
        $this->_relyingParty = null === $relyingParty ? PlatformIdentityRelyingPartyVO::empty() : PlatformIdentityRelyingPartyVO::from($relyingParty);
        $this->_trustedClient = null === $trustedClient ? PlatformIdentityTrustedClientVO::empty() : PlatformIdentityTrustedClientVO::from($trustedClient);
        $this->_roles = PlatformIdentityRolesVO::from($roles);
        $this->_version = null === $version ? PlatformIdentityVersionVO::empty() : PlatformIdentityVersionVO::from($version);
    }
    public function replace(PlatformIdentityAttributes $values): PlatformIdentity
    {
        $value = clone $this;
        $value->_user = $values->getUserOrDefault($this->_user);
        $value->_relyingParty = $values->getRelyingPartyOrDefault($this->_relyingParty);
        $value->_trustedClient = $values->getTrustedClientOrDefault($this->_trustedClient);
        $value->_roles = $values->getRolesOrDefault($this->_roles);
        $value->_version = $values->getVersionOrDefault($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [];
    }
    public static function create(PlatformIdentityAttributes $values): PlatformIdentity
    {
        $value = $values->build();
        $value->recordedEvents[] = new PlatformIdentityCreateEvent($value);
        return $value;
    }
    public function update(PlatformIdentityAttributes $values): PlatformIdentity
    {
        $value = $this->replace($values);
        $value->recordedEvents[] = new PlatformIdentityUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): PlatformIdentity
    {
        $value = clone $this;
        $value->recordedEvents[] = new PlatformIdentityDeleteEvent($value);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $user = $this->getUser();
        if (null !== $user) {
            $data['user'] = ['$ref' => $user->uid() ];
        }
        $relyingParty = $this->getRelyingParty();
        if (null !== $relyingParty) {
            $data['relyingParty'] = ['$ref' => $relyingParty->uid() ];
        }
        $trustedClient = $this->getTrustedClient();
        if (null !== $trustedClient) {
            $data['trustedClient'] = ['$ref' => $trustedClient->uid() ];
        }
        $roles = $this->getRoles();
        if (null !== $roles) {
            $data['roles'] = [];
            foreach ($roles as $row) {
                $jsonRow = [];
                $jsonRow['uid'] = $row->uid();
                $role = $row->getRole()?->uid();
                if ($role) {
                    $jsonRow['role'] = ['$ref' => $role];
                }
                $jsonRow['version'] = $row->getVersion();
                $data['roles'][] = $jsonRow;
            }
        }
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): PlatformIdentityAttributes
    {
        return (new PlatformIdentityAttributes())
          ->uid($this->uid())
          ->user($this->_user)
          ->relyingParty($this->_relyingParty)
          ->trustedClient($this->_trustedClient)
          ->roles($this->_roles)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
